import{assayBands,assayResult,productionLabels}from './special-infection-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function text(x,y,t,size=23){let lines=[],line='';for(let word of String(t).split(' ')){if((line+' '+word).trim().length>32&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);return`<text x="${x}" y="${y}" fill="#f4eee4" text-anchor="middle" font-size="${size}">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?27:0}">${esc(l)}</tspan>`).join('')}</text>`;}
const yShape=(x,y,s=1)=>`<path d="M${x} ${y+40*s}V${y+10*s}l${-23*s} ${-25*s}m${23*s} ${25*s}l${23*s} ${-25*s}" stroke="#e9aa96" stroke-width="${8*s}" fill="none"/>`;
function plant(state){let short=['stunted','nitrate-low'].includes(state),h=short?100:220,body=`<path d="M280 310v-${h}" stroke="#adc1a6" stroke-width="6"/>`;for(let i=0;i<4;i++){let side=i%2?1:-1,y=290-i*h*.24;body+=`<ellipse cx="${280+side*(short?30:48)}" cy="${y}" rx="${short?30:48}" ry="${short?12:20}" transform="rotate(${-side*25} ${280+side*(short?30:48)} ${y})" fill="${['yellow','magnesium-low'].includes(state)?'#dccb91':'#9dbca5'}"/>`;}if(state==='growth')body+='<circle cx="285" cy="235" r="22" fill="#c0a58d"/>';if(['aphid','pests'].includes(state))body+='<ellipse cx="325" cy="180" rx="12" ry="17" fill="#d6c79b"/><path d="M310 170l-15-10m15 20l-15 5m30-15l25-10m-25 20l25 5" stroke="#e4d5ae" stroke-width="3"/>';return body;}
export function specialFigure(w={}){let kind=w.kind||'fusion',s=w.state||'parents',r=w.revealed!==false,body='',desc=w.result||'Symbolic shapes, scales and stages';if(kind==='fusion'){let step=w.step??(s==='purify'?5:s==='clone'?4:s==='hybridoma'?2:s==='lymphocyte'?1:0);if(step>=5){for(let i=0;i<12;i++)body+=yShape(115+(i%4)*110,140+Math.floor(i/4)*70,.5);body+=text(280,350,'Collected and purified antibody');}else if(step===4){for(let i=0;i<6;i++)body+=`<circle cx="${135+(i%3)*145}" cy="${150+Math.floor(i/3)*110}" r="35" fill="#a8c0b1"/>`+yShape(135+(i%3)*145,125+Math.floor(i/3)*110,.35);body+=text(280,360,'Identical cells · same antibody');}else if(step>=2){body='<circle cx="280" cy="210" r="80" fill="#a7c0b5"/><ellipse cx="255" cy="210" rx="20" ry="25" fill="#b69bad"/><ellipse cx="305" cy="210" rx="20" ry="25" fill="#cfb397"/>'+yShape(410,195,.7)+text(280,335,'Divide + make specific antibody');if(step===3)body+='<circle cx="280" cy="210" r="95" fill="none" stroke="#ead3a9" stroke-width="3"/>';}else{body='<circle cx="150" cy="205" r="65" fill="#a7c4c1"/><circle cx="410" cy="205" r="65" fill="#c5af9b"/>'+text(150,315,'Lymphocyte',21)+text(410,315,'Tumour cell',21);if(step===1)body+=yShape(150,95,.7);}body+=text(280,55,productionLabels[step],21);}
else if(kind==='assay'){let step=w.step??3,condition=w.condition||s,b=assayBands(condition,step);body='<rect x="45" y="145" width="470" height="130" rx="30" fill="#d4cebd"/><rect x="80" y="185" width="390" height="50" fill="#f3ead7"/><rect x="85" y="180" width="55" height="60" fill="#c6b49d"/>';if(b.test)body+='<path d="M325 183V237" stroke="#c77f79" stroke-width="9"/>';if(b.control)body+='<path d="M415 183V237" stroke="#96738b" stroke-width="9"/>';body+=text(110,120,'Sample',20)+text(325,120,'T',23)+text(415,120,'C',23);for(let i=0;i<4;i++)body+=`<circle cx="${100+Math.min(step,2)*60+i*16}" cy="${203+(i%2)*14}" r="5" fill="#b97e76"/>`;body+=text(280,320,'Stage'+step+'/3 · '+assayResult(condition,step),23)+text(280,365,'C required before interpreting T',21);}
else if(kind==='binding'){let match=s!=='nonmatch';body='<circle cx="365" cy="205" r="70" fill="#9cbdb8"/>'+text(365,80,'Target antigen',21)+yShape(r&&match?270:165,205,.9);body+=match?'<rect x="290" y="181" width="20" height="20" fill="#ead0a2"/>':'<circle cx="300" cy="191" r="12" fill="#ead0a2"/>';if(s==='fluorescent')body+='<path d="M425 120l20-20m-5 90h30m-30 65l20 20" stroke="#f2dda6" stroke-width="5"/>';if(['payload','harm'].includes(s))body+='<circle cx="270" cy="246" r="15" fill="#e8c599"/>';body+=text(280,350,s==='nonmatch'?'No complementary match':s==='fluorescent'?'Fluorescent label locates binding':s==='payload'?'Linked payload delivered at target':'Specific antibody attachment',21);}
else if(['nutrient','plant','symptoms'].includes(kind)){let state=r?s:'complete';if(['spots','rot','malformed','tmv','blackspot'].includes(state)){body='<path d="M280 315Q70 180 280 90Q490 180 280 315" fill="#9bb9a3"/>';if(state==='malformed')body='<path d="M280 315Q130 280 200 210Q310 190 270 90Q430 200 280 315" fill="#9bb9a3"/>';else for(let i=0;i<8;i++)body+=`<circle cx="${225+i%3*50}" cy="${170+Math.floor(i/3)*45}" r="${state==='rot'?23:12}" fill="${state==='tmv'?'#ddcc97':'#756066'}"/>`;}else body=plant(state);body+=text(280,365,({stunted:'Reduced growth',spots:'Spots',rot:'Decay / rot',growth:'Unusual growth',malformed:'Malformed growth',yellow:'Discolouration',pests:'Visible pests','nitrate-low':'Limited nitrate → reduced growth','magnesium-low':'Limited magnesium → chlorosis',complete:'Suitable matched ion supply',aphid:'Aphid · insect pest',bacterial:'Given: bacterial infection',deficiency:'Given: mineral deficiency'})[state]||state,21);}
else if(kind==='barrier'){if(['bark','shed'].includes(s)){body='<rect x="180" y="90" width="200" height="220" rx="70" fill="#9e8473"/>';for(let i=0;i<5;i++)body+=`<path d="M${210+i*30} 110v180" stroke="#c7ac8e" stroke-width="10"/>`;if(s==='shed'&&r)body+='<path d="M375 110q80 90 30 185" fill="none" stroke="#d1b18e" stroke-width="15"/><circle cx="435" cy="170" r="9" fill="#a7bdb0"/>';body+=text(280,365,s==='shed'?'Outer layer takes surface organisms':'Dead outer stem layers form bark',21);}else{for(let i=0;i<6;i++)body+=`<rect x="${95+(i%3)*125}" y="${140+Math.floor(i/3)*75}" width="115" height="65" fill="#a2bca9" stroke="#e5d4aa" stroke-width="7"/>`;if(s==='cuticle')body+='<path d="M75 115H485" stroke="#d7c5a1" stroke-width="16"/>';body+=text(280,355,s==='cuticle'?'Surface waxy barrier':'Cellulose walls surround cells',21);}}
else if(kind==='chemical'){body=plant('complete');if(s==='antibacterial'){for(let i=0;i<(r?2:7);i++)body+=`<ellipse cx="${130+i*45}" cy="140" rx="15" ry="8" fill="#dec8a1"/>`;body+=text(280,365,'Chemical inhibits bacteria',22);}else body+=text(280,365,'Poison can deter a herbivore',22)+'<path d="M420 220l60-30m-20-5l20 5l-10 20" stroke="#e9cba4" stroke-width="4" fill="none"/>';}
else if(kind==='mechanical'){body=plant('complete');if(s==='thorns')for(let i=0;i<6;i++){let x=i%2?280:265;body+=`<path d="M280 ${120+i*30}l${i%2?35:-35} -10L280 ${140+i*30}z" fill="#d8bf9b"/>`;}if(s==='hairs')for(let i=0;i<16;i++)body+=`<path d="M${190+i%8*24} ${150+Math.floor(i/8)*105}l-6-25" stroke="#e7d6b3" stroke-width="3"/>`;if(s==='fold'&&r)body='<path d="M280 320V100" stroke="#aec2a8" stroke-width="6"/>'+[0,1,2,3].map(i=>`<path d="M280 ${145+i*40}l-22 45m22-45l22 45" stroke="#a4c0aa" stroke-width="16"/>`).join('');if(s==='mimicry')for(let[x,y]of[[232,290],[246,284],[328,237],[342,231],[232,184],[246,178]])body+=`<ellipse cx="${x}" cy="${y}" rx="8" ry="5" fill="#edddad"/>`;body+=text(280,370,({thorns:'Thorns',hairs:'Hairs',open:'Before touch',fold:'After touch · droop/curl',plain:'No misleading occupancy cue',mimicry:'Egg-like marks imitate occupancy'})[s]||s,21);}
else{let names=['Reference','Laboratory','Specific kit'];body=text(280,70,'Different evidence, different questions');for(let i=0;i<3;i++)body+=`<rect x="${25+i*185}" y="145" width="140" height="120" rx="15" fill="${s===['reference','lab','kit'][i]?'#8caeab':'#587780'}"/>`+text(95+i*185,215,names[i],18);}
return`<svg class="infection-diagram special-diagram" viewBox="0 0 560 420" role="img" aria-label="${esc((w.title||'Biology mechanism')+'. '+desc)}">${body}</svg><p class="diagram-caption">${esc(desc)}</p>`;}
